const DataStore = (() => {
  let currentDataset = {
    sourceName: '센서_측정_더미데이터_100건.xlsx (기본 데이터)',
    header: [...DEFAULT_SENSOR_DATA.header],
    numericColumns: [],
    categoricalColumns: [],
    dateColumns: [],
    rows: JSON.parse(JSON.stringify(DEFAULT_SENSOR_DATA.rows)),
    originalRows: JSON.parse(JSON.stringify(DEFAULT_SENSOR_DATA.rows)),
    filteredIndices: new Set()
  };

  const listeners = [];

  function subscribe(listener) {
    listeners.push(listener);
  }

  function notify() {
    listeners.forEach(fn => fn(currentDataset));
  }

  // 컬럼 타입 자동 감지
  function analyzeColumns(header, rows) {
    const numericCols = [];
    const catCols = [];
    const dateCols = [];

    header.forEach(col => {
      let numCount = 0;
      let dateCount = 0;
      let validCount = 0;

      for (let i = 0; i < Math.min(rows.length, 100); i++) {
        const v = rows[i][col];
        if (v !== undefined && v !== null && v !== '') {
          validCount++;
          if (typeof v === 'number' && !isNaN(v)) {
            numCount++;
          } else if (typeof v === 'string') {
            const parsedNum = Number(v.trim());
            if (!isNaN(parsedNum) && v.trim() !== '') {
              numCount++;
            } else if (!isNaN(Date.parse(v)) && (v.includes('-') || v.includes('/') || v.includes(':'))) {
              dateCount++;
            }
          }
        }
      }

      if (validCount > 0 && numCount / validCount >= 0.7) {
        numericCols.push(col);
      } else if (validCount > 0 && dateCount / validCount >= 0.7) {
        dateCols.push(col);
      } else {
        catCols.push(col);
      }
    });

    return { numericCols, catCols, dateCols };
  }

  // 초기화 및 데이터 세팅
  function setDataset(name, header, rawRows) {
    // 수치형 데이터 변환 및 정리
    const { numericCols, catCols, dateCols } = analyzeColumns(header, rawRows);

    const rows = rawRows.map(row => {
      const cleanRow = {};
      header.forEach(h => {
        const val = row[h];
        if (numericCols.includes(h)) {
          if (typeof val === 'number') {
            cleanRow[h] = val;
          } else if (val !== null && val !== undefined && val !== '') {
            const parsed = parseFloat(String(val).replace(/,/g, ''));
            cleanRow[h] = isNaN(parsed) ? null : parsed;
          } else {
            cleanRow[h] = null;
          }
        } else {
          cleanRow[h] = val !== undefined ? val : '';
        }
      });
      return cleanRow;
    });

    currentDataset = {
      sourceName: name,
      header,
      numericColumns: numericCols,
      categoricalColumns: catCols,
      dateColumns: dateCols,
      rows,
      originalRows: JSON.parse(JSON.stringify(rows)),
      filteredIndices: new Set()
    };

    notify();
  }

  // 기본 데이터로 복구
  function resetToDefault() {
    setDataset(
      '센서_측정_더미데이터_100건.xlsx (기본 데이터)',
      [...DEFAULT_SENSOR_DATA.header],
      JSON.parse(JSON.stringify(DEFAULT_SENSOR_DATA.rows))
    );
  }

  // 엑셀 / CSV 파일 파싱 (SheetJS 사용)
  function loadFile(file) {
    return new Promise((resolve, reject) => {
      if (!file) return reject(new Error('파일이 지정되지 않았습니다.'));

      const reader = new FileReader();
      const isCsv = file.name.endsWith('.csv');

      reader.onload = e => {
        try {
          const data = new Uint8Array(e.target.result);
          if (typeof XLSX === 'undefined') {
            throw new Error('엑셀 파서 라이브러리(SheetJS)가 아직 로드되지 않았습니다.');
          }
          const workbook = XLSX.read(data, { type: 'array' });
          const firstSheetName = workbook.SheetNames[0];
          const worksheet = workbook.Sheets[firstSheetName];

          // JSON으로 변환
          const jsonData = XLSX.utils.sheet_to_json(worksheet, { header: 1 });
          if (!jsonData || jsonData.length < 2) {
            throw new Error('시트에 데이터가 충분하지 않습니다 (최소 헤더 1행 + 데이터 1행 필요).');
          }

          const header = jsonData[0].map(h => String(h || '').trim()).filter(h => h.length > 0);
          const rawRows = [];

          for (let i = 1; i < jsonData.length; i++) {
            const rowArr = jsonData[i];
            if (!rowArr || rowArr.length === 0) continue;
            const obj = {};
            let hasAny = false;
            header.forEach((h, colIdx) => {
              const cellVal = rowArr[colIdx];
              obj[h] = cellVal;
              if (cellVal !== undefined && cellVal !== null && cellVal !== '') {
                hasAny = true;
              }
            });
            if (hasAny) rawRows.push(obj);
          }

          if (rawRows.length === 0) {
            throw new Error('유효한 데이터 행을 찾을 수 없습니다.');
          }

          setDataset(file.name, header, rawRows);
          resolve(currentDataset);
        } catch (err) {
          reject(err);
        }
      };

      reader.onerror = () => reject(new Error('파일을 읽는 도중 오류가 발생했습니다.'));
      reader.readAsArrayBuffer(file);
    });
  }

  // 특정 변수의 값 배열 추출 (필터링된 행 제외 가능)
  function getColumnValues(columnName, activeOnly = true) {
    if (!currentDataset.rows) return [];
    return currentDataset.rows
      .filter((_, idx) => !activeOnly || !currentDataset.filteredIndices.has(idx))
      .map(r => r[columnName]);
  }

  // 이상치 행 필터링 토글
  function setFilteredIndices(indicesSet) {
    currentDataset.filteredIndices = indicesSet || new Set();
    notify();
  }

  function clearFilter() {
    currentDataset.filteredIndices = new Set();
    notify();
  }

  // 초기 자동 셋업
  resetToDefault();

  return {
    subscribe,
    getDataset: () => currentDataset,
    loadFile,
    resetToDefault,
    getColumnValues,
    setFilteredIndices,
    clearFilter
  };
})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = DataStore;
}
